  padding: unit calc(2 * unit);

  line-height: calc(4 * unit);
}

.top {
  display: flex;
  align-items: baseline;
  flex-direction: row;
}

.left {
  align-self: center;
  flex-shrink: 0;
}

.label {
  overflow: hidden;
  flex-grow: 1;
  flex-shrink: 1;

  text-align: left;
  white-space: nowrap;
  text-overflow: ellipsis;

  [dir="rtl"] & {
    text-align: right;
    direction: ltr;
  }
